function draw_character(pose,x,y,scale)
 local frames=app.api_version>=5 and character_high or character_low
 local frame=frames[pose] or frames[1]
 for i=1,#frame[3],5 do
  local rx,ry,rw,rh,c=string.byte(frame[3],i,i+4)
  rx,ry,rw,rh,c=rx-33,ry-33,rw-33,rh-33,c-33
  local x1=x+math.floor(rx*32*scale/frame[1])
  local y1=y+math.floor(ry*40*scale/frame[2])
  local x2=x+math.floor((rx+rw)*32*scale/frame[1])
  local y2=y+math.floor((ry+rh)*40*scale/frame[2])
  screen.rect(x1,y1,x2-x1,y2-y1,character_palette[c])
 end
end
